import shlex
from dataclasses import dataclass, field
from hashlib import sha256
from pathlib import Path
from typing import Self

from xenoform_rs import __version__ as version
from xenoform_rs.config import get_config
from xenoform_rs.errors import RustConfigError

# build = false: cargo would otherwise compile and run any build.rs that finds its way into the module folder. Link
# settings are passed by `cargo rustc` instead, and only recorded here (see `make_source`)
_CARGO_TEMPLATE = """
# Generated by xenoform-rs {version}. DO NOT EDIT DIRECTLY.{rustc_args}

[package]
name = "{module_name}"
edition = "{edition}"
build = false

[lib]
crate-type = ["cdylib"]

[profile.release]
{profile_overrides}

[dependencies]
{dependencies}
pyo3 = {{ version = "{pyo3_version}", features = ["jiff-02", "extension-module", "abi3-py313"] }}
"""


_MODULE_TEMPLATE = """
#![allow(clippy::needless_lifetimes)]
#![allow(clippy::extra_unused_lifetimes)]
#![allow(non_upper_case_globals)]
#![allow(non_snake_case)]
{modules}

#[pyo3::pymodule{freethreaded}]
mod {module_name} {{
use pyo3::prelude::*;
    {use_statements}
    {crate_use_statements}

    #[pymodule_export]
    const __doc__: &str = "{module_name} module generated by xenoform-rs {version}";

    #[pymodule_export]
    const __checksum__: &str = "__HASH__";

    {constants}

    {function_definitions}
}}
"""

_FUNCTION_DEFINITION_TEMPLATE = """
{help}
#[pyfunction]
#[pyo3 (signature=({arg_defs}))]
fn {function_name}<'py>{function_body}

"""


def _format_help(help: str | None) -> str:
    if not help:
        return ""
    return "\n".join(f"/// {line}" for line in help.split("\n"))


@dataclass(frozen=True)
class FunctionSpec:
    """
    Dataclass defining a function
    """

    name: str
    body: str
    py: bool
    arg_annotations: str
    scope: tuple[str, ...]
    help: str | None = None

    def qualified_name(self) -> str:
        if self.scope:
            return f"_{'_'.join(self.scope)}_{self.name}"
        return f"_{self.name}"


def _append_profile(existing: dict[str, str], new: dict[str, str]) -> dict[str, str]:
    common_keys = existing.keys() & new.keys()
    for k in common_keys:
        if existing[k] != new[k]:
            raise RustConfigError(f"Conflicting profile values for {k}: {existing[k]} vs {new[k]}")
    return existing | new


def _check_link_settings(settings: list[str]) -> None:
    # they're written into a comment in Cargo.toml, which can't contain control characters other than tab: a line break
    # would end the comment, and the rest would be read as TOML
    for setting in settings:
        if any(c != "\t" and (c < " " or c == "\x7f") for c in setting):
            raise RustConfigError(f"Link setting contains a control character: {setting!r}")


def _append_unique[T](existing: list[T], new: list[T]) -> list[T]:
    return existing + [item for item in dict.fromkeys(new) if item not in existing]


@dataclass
class ModuleSpec:
    """
    Dataclass for accumulating functions to be built within a module
    """

    functions: set[FunctionSpec] = field(default_factory=set[FunctionSpec])
    deps: set[str] = field(default_factory=set[str])
    uses: set[str] = field(default_factory=set[str])
    profile: dict[str, str] = field(default_factory=dict[str, str])
    edition: str | None = None  # will default to "2024"
    modules: set[Path] = field(default_factory=set[Path])
    constants: set[str] = field(default_factory=set[str])
    # lists, not sets: the linker searches paths, and resolves static libraries, in the order given
    link_search: list[Path] = field(default_factory=list[Path])
    link_libs: list[str] = field(default_factory=list[str])
    link_args: list[str] = field(default_factory=list[str])

    def add_function(
        self,
        function: FunctionSpec,
        *,
        deps: list[str] | None = None,
        uses: list[str] | None = None,
        profile: dict[str, str] | None = None,
        edition: str | None = None,
        modules: list[Path] | None = None,
        constants: list[str] | None = None,
        link_search: list[Path] | None = None,
        link_libs: list[str] | None = None,
        link_args: list[str] | None = None,
    ) -> Self:
        _check_link_settings([str(p) for p in link_search or []] + (link_libs or []) + (link_args or []))
        self.functions.add(function)
        self.deps |= set(deps or [])
        self.uses |= set(uses or [])
        self.profile = _append_profile(self.profile, profile or {})
        self.modules |= set(modules or [])
        # identical definitions from different functions collapse; conflicting ones are left for rustc to reject (E0428)
        self.constants |= set(constants or [])
        self.link_search = _append_unique(self.link_search, link_search or [])
        self.link_libs = _append_unique(self.link_libs, link_libs or [])
        self.link_args = _append_unique(self.link_args, link_args or [])
        if edition and self.edition and edition != self.edition:
            raise RustConfigError(f"Incompatible edition values: {edition} when {self.edition} has already been set")
        self.edition = edition or self.edition
        return self

    def rustc_args(self) -> list[str]:
        """The link settings as arguments for rustc"""
        return (
            [f"-Lnative={p}" for p in self.link_search]
            + [f"-l{lib}" for lib in self.link_libs]
            + [f"-Clink-arg={arg}" for arg in self.link_args]
        )

    def make_source(self, module_name: str) -> tuple[str, str, str]:
        # recorded in Cargo.toml so they're seen with the build settings, and hashed with them. Comment only, as cargo
        # can't pass them to the module's crate alone: `cargo rustc` does. Quoted, as ["a b"] and ["a", "b"] are
        # different args. Without any there's no line, so modules without link settings keep their hash
        rustc_args = self.rustc_args()
        # every set is sorted: python randomises string hashing per process, so set order changes from run to run, and
        # the generated source (hence the hash) must not
        module = _CARGO_TEMPLATE.format(
            version=version,
            rustc_args=f"\n# rustc args, passed by cargo rustc: {shlex.join(rustc_args)}" if rustc_args else "",
            pyo3_version=get_config().pyo3_version,
            module_name=module_name,
            edition=self.edition or "2024",  # only default at the point when Cargo.toml is generated
            profile_overrides="\n".join(f'{k} = "{v}"' for k, v in self.profile.items()),
            dependencies="\n".join(sorted(self.deps)),
        )

        # sort to prevent rebuilding when nothing has changed but the function ordering
        function_defs = "\n".join(
            sorted(
                _FUNCTION_DEFINITION_TEMPLATE.format(
                    function_name=f.qualified_name(),
                    lifetime="<'py>" if f.py else "",
                    function_body=f.body,
                    arg_defs=f.arg_annotations,
                    help=_format_help(f.help),
                )
                for f in self.functions
            )
        )

        # create the code without the hash. Deliberately independent of the interpreter ABI: each ABI builds
        # into its own target dir (see `get_target_dir`), so the binary the checksum is compared against is
        # already the current interpreter's — the sources need only answer whether *they* changed.
        code = _MODULE_TEMPLATE.format(
            version=version,
            module_name=module_name,
            modules="\n".join(f"pub mod {m.stem};" for m in sorted(self.modules)),
            freethreaded="(gil_used = true)" if get_config().disable_ft else "(gil_used = false)",
            use_statements="\n".join(f"use {u};" for u in sorted(self.uses)),
            crate_use_statements="\n".join(f"use crate::{m.stem};" for m in sorted(self.modules)),
            constants="\n".join(sorted(self.constants)),
            function_definitions=function_defs,
        )

        # hashed unformatted: rustfmt runs only when writing lib.rs, so checking a module doesn't need it, and the hash
        # doesn't depend on whether (or which version of) rustfmt is installed, e.g. rustup's minimal profile has none
        hash = sha256(module.encode("utf-8") + code.encode("utf-8"))
        # unlike these, linked libraries aren't hashed (only the settings naming them, in Cargo.toml): finding them
        # means resolving platform-specific names in the search paths. So rebuilding a static library, which is copied
        # into the module, doesn't rebuild it
        for m in sorted(self.modules):
            hash.update(m.read_bytes())

        return module, code, hash.hexdigest()
